    INSERT INTO SanPham(TenSP,MoTa,HinhAnh,Gia,DonViTinh,SoLuongTon,HanSuDung,NhietDoBaoQuan,MaDanhMuc)
    VALUES(N'Đậu phộng hạt khô',N'Hạt đậu phộng sống đã tách vỏ cứng, còn vỏ lụa; dùng rang, nấu chè hoặc làm muối đậu. Tên gọi khác: lạc, đậu phộng, hạt lạc. Quy cách có sẵn: Gói 200g (200 g), Gói 500g (500 g).',N'/api/v1/product-images/catalog-38-photo.jpg',12000,N'gói',0,DATEADD(DAY,180,GETDATE()),N'Nơi khô ráo, kín, tránh ẩm',5);

SET @ParentId=NULL;
SELECT TOP 1 @ParentId=MaSP FROM SanPham WITH (UPDLOCK,HOLDLOCK)
WHERE TenSP=N'Đậu phộng hạt khô' AND MaSPCha IS NULL AND TrangThaiXoa=0 ORDER BY MaSP;
IF @ParentId IS NOT NULL
BEGIN
    IF NOT EXISTS (SELECT 1 FROM SanPham WITH (UPDLOCK,HOLDLOCK) WHERE MaSPCha=@ParentId AND TenLoai=N'Gói 200g')
        INSERT INTO SanPham(MaSPCha,TenLoai,TenSP,MoTa,HinhAnh,Gia,DonViTinh,SoLuongTon,HanSuDung,NhietDoBaoQuan,MaDanhMuc)
        VALUES(@ParentId,N'Gói 200g',N'Đậu phộng hạt khô - Gói 200g',N'Hạt đậu phộng sống đã tách vỏ cứng, còn vỏ lụa; dùng rang, nấu chè hoặc làm muối đậu. Tên gọi khác: lạc, đậu phộng, hạt lạc. Quy cách: Gói 200g. Khối lượng tham khảo 200 g; giá tính cho một gói.',N'/api/v1/product-images/catalog-38-photo.jpg',12000,N'gói',40,DATEADD(DAY,180,GETDATE()),N'Nơi khô ráo, kín, tránh ẩm',5);
    IF NOT EXISTS (SELECT 1 FROM SanPham WITH (UPDLOCK,HOLDLOCK) WHERE MaSPCha=@ParentId AND TenLoai=N'Gói 500g')
        INSERT INTO SanPham(MaSPCha,TenLoai,TenSP,MoTa,HinhAnh,Gia,DonViTinh,SoLuongTon,HanSuDung,NhietDoBaoQuan,MaDanhMuc)
        VALUES(@ParentId,N'Gói 500g',N'Đậu phộng hạt khô - Gói 500g',N'Hạt đậu phộng sống đã tách vỏ cứng, còn vỏ lụa; dùng rang, nấu chè hoặc làm muối đậu. Tên gọi khác: lạc, đậu phộng, hạt lạc. Quy cách: Gói 500g. Khối lượng tham khảo 500 g; giá tính cho một gói.',N'/api/v1/product-images/catalog-38-photo.jpg',30000,N'gói',32,DATEADD(DAY,180,GETDATE()),N'Nơi khô ráo, kín, tránh ẩm',5);
END;

COMMIT TRANSACTION;
